1	<!DOCTYPE html>
2	<html lang="mk">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Зелена Империја — од семка до берба</title>
7	<style>
8	/* ═══════════════════════════════════════════════════════════════
9	   ЗЕЛЕНА ИМПЕРИЈА — стилови
10	   ═══════════════════════════════════════════════════════════════ */
11	:root{
12	  --pozadina:#0e1611; --panel:#16221b; --panel-2:#1d2d24; --rab:#2b4034;
13	  --tekst:#e8f2ea; --tekst-slab:#8fa899; --zelena:#4ade80; --zelena-temna:#22c55e;
14	  --zlato:#fbbf24; --crvena:#f87171; --sina:#60a5fa; --violet:#c084fc;
15	  --r:12px; --sen:0 4px 20px rgba(0,0,0,.4);
16	}
17	*{box-sizing:border-box;margin:0;padding:0}
18	body{
19	  background:radial-gradient(ellipse at 50% -10%,#1c3527 0%,var(--pozadina) 60%);
20	  color:var(--tekst); font-family:"Segoe UI",Roboto,system-ui,sans-serif;
21	  min-height:100vh; padding:14px; font-size:14px;
22	}
23	button{font-family:inherit;cursor:pointer;border:none;border-radius:8px;
24	  transition:transform .08s,filter .15s}
25	button:hover:not(:disabled){filter:brightness(1.15)}
26	button:active:not(:disabled){transform:translateY(1px)}
27	button:disabled{opacity:.35;cursor:not-allowed}
28	
29	/* ── Заглавие ───────────────────────────────────────────────── */
30	.zaglavje{
31	  display:flex;flex-wrap:wrap;gap:10px;align-items:center;
32	  background:linear-gradient(135deg,var(--panel-2),var(--panel));
33	  border:1px solid var(--rab);border-radius:var(--r);padding:12px 16px;
34	  margin-bottom:14px;box-shadow:var(--sen)
35	}
36	.logo{font-size:19px;font-weight:800;letter-spacing:.3px;
37	  background:linear-gradient(90deg,var(--zelena),var(--zlato));
38	  -webkit-background-clip:text;background-clip:text;color:transparent;white-space:nowrap}
39	.hud{display:flex;flex-wrap:wrap;gap:8px;margin-left:auto;align-items:center}
40	.stat{background:#0d1712;border:1px solid var(--rab);border-radius:9px;
41	  padding:6px 12px;display:flex;flex-direction:column;gap:2px;min-width:88px}
42	.stat b{font-size:15px;line-height:1}
43	.stat span{font-size:10px;color:var(--tekst-slab);text-transform:uppercase;letter-spacing:.5px}
44	.xp-lenta{height:4px;background:#0d1712;border-radius:3px;overflow:hidden;
45	  width:110px;border:1px solid var(--rab)}
46	.xp-lenta>i{display:block;height:100%;background:linear-gradient(90deg,var(--violet),var(--sina));
47	  transition:width .3s}
48	
49	/* ── Распоред ───────────────────────────────────────────────── */
50	.raspored{display:grid;grid-template-columns:1fr 370px;gap:14px;align-items:start}
51	@media(max-width:1020px){.raspored{grid-template-columns:1fr}}
52	
53	/* ── Леи ────────────────────────────────────────────────────── */
54	.lei{display:grid;grid-template-columns:repeat(auto-fill,minmax(178px,1fr));gap:12px}
55	.leja{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
56	  padding:10px;display:flex;flex-direction:column;gap:8px;box-shadow:var(--sen)}
57	.leja.zaklucena{opacity:.55;border-style:dashed}
58	.leja.zrela{border-color:var(--zlato);box-shadow:0 0 0 1px var(--zlato),0 4px 20px rgba(251,191,36,.18)}
59	.leja.bolna{border-color:var(--crvena)}
60	.leja-glava{display:flex;justify-content:space-between;align-items:baseline;gap:6px}
61	.leja-br{font-size:11px;color:var(--tekst-slab);text-transform:uppercase;letter-spacing:.6px}
62	.leja-faza{font-size:11px;font-weight:700;color:var(--zelena)}
63	.leja.zrela .leja-faza{color:var(--zlato)}
64	
65	/* Сцена со растение */
66	.scena{position:relative;height:132px;border-radius:9px;overflow:hidden;
67	  background:linear-gradient(180deg,#0b1a13 0%,#102a1c 68%,#3a2a18 68%,#291d10 100%)}
68	.scena svg{position:absolute;inset:0;width:100%;height:100%}
69	.scena svg g{transition:transform .3s ease-out,opacity .4s}
70	.znak-sorta{position:absolute;top:5px;left:6px;font-size:9px;font-weight:700;
71	  color:var(--tekst-slab);background:rgba(0,0,0,.45);padding:2px 5px;border-radius:4px}
72	.znak-stetnik{position:absolute;top:5px;right:6px;font-size:9px;font-weight:800;
73	  letter-spacing:.4px;color:#2a0606;background:var(--crvena);padding:2px 6px;
74	  border-radius:20px;animation:trepka 1.1s infinite;cursor:help}
75	.znak-stetnik:empty{display:none}
76	@keyframes trepka{0%,100%{opacity:1}50%{opacity:.35}}
77	.prazna-poraka{position:absolute;inset:0;display:flex;align-items:center;
78	  justify-content:center;color:var(--tekst-slab);font-size:12px;text-align:center;padding:8px}
79	
80	/* Ленти за статус */
81	.lenti{display:flex;flex-direction:column;gap:4px}
82	.lenta{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--tekst-slab)}
83	.lenta i{font-style:normal;width:44px;text-align:left;font-size:9px;letter-spacing:.2px}
84	.lenta .zica{flex:1;height:6px;background:#0d1712;border-radius:4px;overflow:hidden;
85	  border:1px solid var(--rab)}
86	.lenta .zica>b{display:block;height:100%;border-radius:3px;transition:width .25s,background .25s}
87	.lenta u{text-decoration:none;width:26px;text-align:right;font-variant-numeric:tabular-nums}
88	
89	/* Дугмиња на леја */
90	.akcii{display:grid;grid-template-columns:1fr 1fr;gap:5px}
91	.akcii button{font-size:11px;font-weight:700;padding:7px 4px;
92	  background:var(--panel-2);color:var(--tekst);border:1px solid var(--rab)}
93	.akcii button.glavna{grid-column:1/-1;background:linear-gradient(135deg,var(--zelena-temna),#15803d);
94	  color:#04150b;border-color:transparent}
95	.akcii button.zlatna{grid-column:1/-1;background:linear-gradient(135deg,var(--zlato),#d97706);
96	  color:#2a1a00;border-color:transparent}
97	.akcii button.opasna{grid-column:1/-1;background:linear-gradient(135deg,var(--crvena),#dc2626);
98	  color:#2a0606;border-color:transparent}
99	
100	/* ── Странични панели ───────────────────────────────────────── */
101	.strana{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
102	  box-shadow:var(--sen);overflow:hidden;position:sticky;top:14px}
103	.jazicinja{display:flex;background:#0d1712;border-bottom:1px solid var(--rab)}
104	.jazicinja button{flex:1;padding:11px 4px;font-size:11.5px;font-weight:700;
105	  background:transparent;color:var(--tekst-slab);border-radius:0;border-bottom:2px solid transparent}
106	.jazicinja button.aktivno{color:var(--zelena);border-bottom-color:var(--zelena);background:var(--panel)}
107	.sodrzina{padding:12px;max-height:calc(100vh - 190px);overflow-y:auto}
108	.sodrzina::-webkit-scrollbar{width:7px}
109	.sodrzina::-webkit-scrollbar-thumb{background:var(--rab);border-radius:4px}
110	
111	.stavka{background:var(--panel-2);border:1px solid var(--rab);border-radius:9px;
112	  padding:9px 10px;margin-bottom:8px;display:flex;flex-direction:column;gap:6px}
113	.stavka.zakluceno{opacity:.5}
114	.stavka-glava{display:flex;justify-content:space-between;align-items:center;gap:8px}
115	.stavka-ime{font-weight:700;font-size:13px}
116	.stavka-cena{color:var(--zlato);font-weight:800;font-size:13px;white-space:nowrap}
117	.stavka-opis{font-size:11px;color:var(--tekst-slab);line-height:1.45}
118	.stavka button{padding:7px;font-size:11.5px;font-weight:700;
119	  background:linear-gradient(135deg,var(--zelena-temna),#15803d);color:#04150b}
120	.stavka button.sina{background:linear-gradient(135deg,var(--sina),#2563eb);color:#03142c}
121	.stavka .dve{display:grid;grid-template-columns:1fr 1fr;gap:6px}
122	.prazno{color:var(--tekst-slab);font-size:12px;text-align:center;padding:26px 10px;line-height:1.6}
123	
124	.oznaka{display:inline-block;padding:2px 7px;border-radius:20px;font-size:10px;font-weight:800}
125	.o-vrven{background:rgba(251,191,36,.18);color:var(--zlato)}
126	.o-odlicen{background:rgba(74,222,128,.18);color:var(--zelena)}
127	.o-sreden{background:rgba(96,165,250,.18);color:var(--sina)}
128	.o-slab{background:rgba(248,113,113,.18);color:var(--crvena)}
129	
130	.napredok{height:6px;background:#0d1712;border:1px solid var(--rab);
131	  border-radius:4px;overflow:hidden}
132	.napredok>i{display:block;height:100%;background:linear-gradient(90deg,var(--zlato),#f59e0b);
133	  transition:width .3s}
134	
135	/* ── Известувања ────────────────────────────────────────────── */
136	.izvestuvanja{position:fixed;right:14px;bottom:14px;display:flex;flex-direction:column;
137	  gap:7px;z-index:60;max-width:310px;pointer-events:none}
138	.toast{background:var(--panel-2);border:1px solid var(--rab);border-left:3px solid var(--zelena);
139	  border-radius:8px;padding:9px 13px;font-size:12.5px;box-shadow:var(--sen);
140	  animation:vlez .25s ease-out}
141	.toast.greska{border-left-color:var(--crvena)}
142	.toast.pari{border-left-color:var(--zlato)}
143	@keyframes vlez{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}
144	
145	/* ── Модал ──────────────────────────────────────────────────── */
146	.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;
147	  align-items:center;justify-content:center;z-index:80;padding:18px}
148	.modal.otvoren{display:flex}
149	.modal-kutija{background:var(--panel);border:1px solid var(--rab);border-radius:var(--r);
150	  padding:18px;max-width:430px;width:100%;max-height:82vh;overflow-y:auto;box-shadow:var(--sen)}
151	.modal-naslov{font-size:16px;font-weight:800;margin-bottom:12px}
152	.modal-zatvori{width:100%;padding:9px;margin-top:6px;background:var(--panel-2);
153	  color:var(--tekst-slab);border:1px solid var(--rab);font-weight:700;font-size:12px}
154	</style>
155	</head>
156	<body>
157	
158	<header class="zaglavje">
159	  <div class="logo">ЗЕЛЕНА ИМПЕРИЈА</div>
160	  <div class="hud">
161	    <div class="stat"><b id="hud-pari">0</b><span>Денари</span></div>
162	    <div class="stat"><b id="hud-nivo">1</b><span>Ниво</span><div class="xp-lenta"><i id="hud-xp"></i></div></div>
163	    <div class="stat"><b id="hud-den">1</b><span>Ден</span></div>
164	    <div class="stat"><b id="hud-lampa">Флуо</b><span>Ламба</span></div>
165	    <div class="stat"><b id="hud-grama">0 г</b><span>Вкупна берба</span></div>
166	  </div>
167	</header>
168	
169	<div class="raspored">
170	  <main class="lei" id="lei"></main>
171	
172	  <aside class="strana">
173	    <nav class="jazicinja">
174	      <button data-jaz="prodavnica" class="aktivno">Продавница</button>
175	      <button data-jaz="sushara">Сушара</button>
176	      <button data-jaz="magacin">Магацин</button>
177	      <button data-jaz="nadgradbi">Надградби</button>
178	    </nav>
179	    <div class="sodrzina" id="sodrzina"></div>
180	  </aside>
181	</div>
182	
183	<div class="izvestuvanja" id="izvestuvanja"></div>
184	
185	<div class="modal" id="modal">
186	  <div class="modal-kutija">
187	    <div class="modal-naslov" id="modal-naslov"></div>
188	    <div id="modal-telo"></div>
189	    <button class="modal-zatvori" onclick="zatvoriModal()">Затвори</button>
190	  </div>
191	</div>
192	
193	<script>
194	"use strict";
195	/* ═══════════════════════════════════════════════════════════════
196	   1. КОНФИГУРАЦИЈА
197	   ═══════════════════════════════════════════════════════════════ */
198	const KONFIG = {
199	  TIK_MS: 250,            // реални милисекунди по тик
200	  CHASA_PO_TIK: 3,        // игрални часови по тик  →  8 тика = 1 ден = 2 сек
201	  MAX_TIKOVI_NADOMEST: 8, // капа за наваксување кога табот бил во заднина
202	  AVTOSEJV_TIKOVI: 40,    // зачувај на секои 10 реални секунди
203	  KLUC_SEJV: "zelena-imperija-sejv",
204	  VERZIJA: 1,
205	
206	  POCETNI_PARI: 8000,
207	  POCETNI_LEI: 4,
208	  MAX_LEI: 12,
209	  CENA_LEJA_OSNOVA: 75000,
210	  CENA_LEJA_RAST: 1.6,
211	
212	  // Времетраење на фазите во игрални часови (пред множителот `traenje`)
213	  CHASA_NIKNENJE: 3 * 24,
214	  CHASA_VEGETACIJA: 21 * 24,
215	  CHASA_CVETANJE: 50 * 24,
216	  CHASA_ZRELO_PROZOR: 14 * 24,
217	
218	  // Грижа
219	  VODA_PAD_DEN: 6, HRANA_PAD_DEN: 3,
220	  VODA_DOZA: 45, HRANA_DOZA: 40, CENA_HRANA: 250,
221	  VODA_MIN: 20, VODA_MAX: 95, HRANA_MIN: 15, HRANA_MAX: 95,
222	  AVTO_VODA_PRAG: 55, RABOTNIK_PRAG: 40,
223	
224	  // Здравје — промена по тик
225	  STETA_SUSA: 1.2, STETA_DAVENJE: 0.8,
226	  STETA_GLAD: 0.9, STETA_PREGOR: 0.6,
227	  OPORAVUVANJE: 0.4,
228	  KAZNA_PREZRELOST_DEN: 1.5,
229	
230	  SANSA_STETNIK_DEN: 0.03, KLIMA_NAMALUVANJE: 0.4,
231	  SUSHARA_ZABRZUVANJE: 1.4,
232	  VLAZNO_VO_SUVO: 0.22,       // мокра маса → сува маса
233	  CENA_LABORATORIJA: 900, BONUS_LABORATORIJA: 1.18,
234	  PAZAR_DRIFT: 0.03, PAZAR_MIN: 0.75, PAZAR_MAX: 1.35
235	};
236	
237	/* ═══════════════════════════════════════════════════════════════
238	   2. СОДРЖИНА — сортите, ламбите, надградбите, штетниците
239	   Балансот се менува ТУКА, не во логиката подолу.
240	   ═══════════════════════════════════════════════════════════════ */
241	
242	// traenje = множител на времетраењето. 0.85 значи 15% ПОБРЗО,
243	// 1.35 значи 35% ПОБАВНО. Скапите сорти растат побавно, но даваат повеќе.
244	const SORTI = [
245	  {id:"skopsko", ime:"Скопско Зелено",     cena:150,  traenje:0.85, prinos:60,  genetika:0.45, cenaPoGram:90,  nivo:1},
246	  {id:"vardar",  ime:"Вардар Куш",         cena:400,  traenje:1.00, prinos:85,  genetika:0.60, cenaPoGram:140, nivo:2},
247	  {id:"pelister",ime:"Пелистерска Магла",  cena:900,  traenje:1.10, prinos:110, genetika:0.72, cenaPoGram:200, nivo:4},
248	  {id:"ohrid",   ime:"Охридски Кристал",   cena:1800, traenje:1.15, prinos:130, genetika:0.82, cenaPoGram:280, nivo:6},
249	  {id:"shar",    ime:"Шар Планина Хаза",   cena:3200, traenje:1.25, prinos:155, genetika:0.90, cenaPoGram:380, nivo:8},
250	  {id:"dojran",  ime:"Дојранска Ноќ",      cena:6000, traenje:1.35, prinos:185, genetika:0.97, cenaPoGram:520, nivo:11}
251	];
252	
253	const LAMPI = [
254	  {id:"fluo", ime:"Флуо",                cena:0,     prinosMult:1.00, kvalitetBonus:0,  nivo:1},
255	  {id:"hps",  ime:"ХПС",                 cena:220000,prinosMult:1.15, kvalitetBonus:4,  nivo:2},
256	  {id:"led",  ime:"ЛЕД",                 cena:700000,prinosMult:1.30, kvalitetBonus:8,  nivo:5},
257	  {id:"leds", ime:"ЛЕД Full-Spectrum",   cena:2400000,prinosMult:1.50, kvalitetBonus:14, nivo:9}
258	];
259	
260	const NADGRADBI = [
261	  {id:"navodnuvanje", ime:"Автоматско наводнување", cena:240000,
262	   opis:"Водата никогаш не паѓа под 55%. Крајот на рачното полевање."},
263	  {id:"klima", ime:"Клима-систем", cena:360000,
264	   opis:"Ја намалува шансата за штетници за 60%."},
265	  {id:"sushara", ime:"Професионална сушара", cena:300000,
266	   opis:"Сушењето е 40% побрзо, а идеалниот прозорец се шири на 8–14 дена."},
267	  {id:"rabotnik", ime:"Вработен работник", cena:900000,
268	   opis:"Автоматски ѓубри кога хранливите материи ќе паднат под 40%."}
269	];
270	
271	const NASTANI = [
272	  {id:"grini",  ime:"Пајакови грини",      kratko:"ГРИНИ", steta:0.9, tretman:"Акарицид",   cena:900, samoCvetanje:false},
273	  {id:"muvla",  ime:"Мувла",               kratko:"МУВЛА", steta:1.4, tretman:"Фунгицид",   cena:1400, samoCvetanje:true},
274	  {id:"voshki", ime:"Лисни вошки",         kratko:"ВОШКИ", steta:0.6, tretman:"Инсектицид", cena:700,  samoCvetanje:false},
275	  {id:"azot",   ime:"Недостаток на азот",  kratko:"АЗОТ",  steta:0.5, tretman:null,         cena:0,   samoCvetanje:false}
276	];
277	
278	const OCENKI = [
279	  {prag:85, ime:"Врвен",   klasa:"o-vrven",   mult:2.2},
280	  {prag:70, ime:"Одличен", klasa:"o-odlicen", mult:1.6},
281	  {prag:50, ime:"Среден",  klasa:"o-sreden",  mult:1.1},
282	  {prag:0,  ime:"Слаб",    klasa:"o-slab",    mult:0.6}
283	];
284	
285	const FAZI = {
286	  NIKNENJE:   {ime:"Никнење"},
287	  VEGETACIJA: {ime:"Вегетација"},
288	  CVETANJE:   {ime:"Цветање"},
289	  ZRELO:      {ime:"Зрело за берба"}
290	};
291	
292	const TEKST = {
293	  nemaPari:"Немаш доволно денари.",
294	  nemaSemki:"Немаш семки. Купи од продавницата.",
295	  potrebnoNivo:n=>`Потребно е ниво ${n}.`,
296	  kupenoSeme:s=>`Купено семе: ${s}.`,
297	  zasadeno:s=>`Засадено: ${s}.`,
298	  polevanje:"Полеано.",
299	  hranenje:"Наѓубрено.",
300	  tretirano:t=>`Применето: ${t}.`,
301	  samoGubrenje:"Ова се лекува со ѓубрење, не со третман.",
302	  berba:(g,s)=>`Берба на ${s}: ${g} г мокра маса. Оди во сушара.`,
303	  sushenjeGotovo:(g,o)=>`Сушењето заврши: ${g} г, оценка „${o}".`,
304	  prodadeno:(g,p)=>`Продадени ${g} г за ${formatPari(p)} ден.`,
305	  analiza:t=>`Анализата е готова: ${t}% ТХЦ. Сертифициран производ.`,
306	  novoNivo:n=>`Ново ниво: ${n}!`,
307	  novaLeja:"Нова леја е отклучена!",
308	  kupenaNadgradba:i=>`Купено: ${i}.`,
309	  sejvGreska:"Зачувувањето не успеа — играта продолжува во меморија.",
310	  vcitajGreska:"Оштетена зачувана игра — почнуваме одново.",
311	  starVerzija:"Зачуваната игра е од стара верзија — почнуваме одново.",
312	  prezrelo:"Растението презрева — квалитетот паѓа!"
313	};
314	
315	/* ═══════════════════════════════════════════════════════════════
316	   3. СОСТОЈБА
317	   ═══════════════════════════════════════════════════════════════ */
318	let sostojba;
319	let brojacTikovi = 0;
320	let aktivnoJazice = "prodavnica";
321	let panelValjaSe = true;         // dirty flag за страничниот панел
322	let posledenTajmer = 0;
323	let sledenId = 1;
324	
