346	   4. ПОМОШНИ ФУНКЦИИ
347	   ═══════════════════════════════════════════════════════════════ */
348	const stegni = (v, min, max) => Math.min(max, Math.max(min, v));
349	const najdiSorta  = id => SORTI.find(s => s.id === id);
350	const najdiNastan = id => NASTANI.find(n => n.id === id);
351	const tekovnaLampa = () => LAMPI[stegni(sostojba.lampa, 0, LAMPI.length - 1)];
352	const formatPari = n => Math.round(n).toLocaleString("mk-MK");
353	const potrebnoIskustvo = nivo => Math.round(500 * Math.pow(nivo, 1.5));
