394	/** Сува маса во грамови од една берба. */
395	function presmetajPrinos(sorta, prosekZdravje, lampa){
396	  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
397	  return sorta.prinos * Math.pow(zdrav, 1.2) * lampa.prinosMult;
