400	/**
401	 * ╔══════════════════════════════════════════════════════════════╗
402	 * ║  ОВА Е ГЛАВНОТО КОПЧЕ ЗА БАЛАНС НА ИГРАТА.                   ║
403	 * ║  Слободно замени го телото — потписот останува ист.          ║
404	 * ╚══════════════════════════════════════════════════════════════╝
405	 *
406	 * Враќа квалитет 0–100, кој потоа станува оценка (Врвен → Слаб)
407	 * и директно ја множи продажната цена.
408	 *
409	 * @param {number} prosekZdravje    0–100, просечно здравје низ целиот живот
410	 * @param {number} tochnostSushenje 0–1,  1.0 = совршено погоден прозорец за сушење
411	 * @param {number} genetika         0–1,  вродениот потенцијал на сортата
412	 * @param {number} lampaBonus       0–14, бонус од ламбата
413	 * @param {number} deoviSoStetnik   цели денови поминати со нетретиран штетник
414	 * @returns {number} квалитет 0–100
415	 *
416	 * TODO(ти):  Ова е компромис меѓу ДВЕ различни игри и одлуката е твоја:
417	 *
418	 *   А) „Наградувај трпение" — дај му голема тежина на `tochnostSushenje`
419	 *      и остра казна за `deoviSoStetnik`. Играчот што внимава на секое
420	 *      растение заработува многукратно повеќе од оној што сади масовно.
421	 *
422	 *   Б) „Наградувај обем" — дај му поголема тежина на `genetika` и
423	 *      `lampaBonus`, а помала на грижата. Тогаш вистинската стратегија
424	 *      е да купуваш подобри семки и повеќе леи, а не да кликаш.
425	 *
426	 * Долунаведената имплементација е намерно во средина (грижата носи
427	 * најмногу, но генетиката поставува таван), за играта да е играбилна
428	 * веднаш. Замени ја кога ќе решиш во која насока ја сакаш играта.
429	 */
430	function presmetajKvalitet(prosekZdravje, tochnostSushenje, genetika, lampaBonus, deoviSoStetnik){
431	  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
432	  const suvo  = stegni(tochnostSushenje, 0, 1);
433	  const gen   = stegni(genetika, 0, 1);
434	
435	  // Грижата е основата (0–60), сушењето ја модулира.
436	  const osnova = 60 * Math.pow(zdrav, 1.1) * (0.55 + 0.45 * suvo);
437	  // Генетиката поставува таван кон кој се стреми резултатот (0–30).
438	  const taban  = 30 * gen;
439	  // Опремата е мал, но сигурен додаток.
440	  const oprema = stegni(lampaBonus, 0, 14);
441	  // Секој ден со штетник боли трајно.
442	  const kazna  = Math.max(0, deoviSoStetnik) * 2.5;
443	
444	  return stegni(osnova + taban + oprema - kazna, 0, 100);
445	}
446	
447	/** Претвора поминати денови сушење во точност 0–1 (види §5 од спецификацијата). */
448	function tochnostOdSushenje(denovi, imaSushara){
449	  const d1 = imaSushara ? 8 : 9;      // прв идеален ден
450	  const d2 = imaSushara ? 14 : 12;    // последен идеален ден
451	  if (denovi <  d1)     return 0.55;  // предвреме
452	  if (denovi <= d2)     return 1.00;  // идеално
453	  if (denovi <= d2 + 4) return 0.80;  // прифатливо
454	  return 0.65;                        // пресушено
455	}
456	
457	/** ТХЦ процент, изведен од квалитетот и генетиката. */
458	function presmetajTHC(kvalitet, genetika){
459	  return +(8 + 22 * genetika * (stegni(kvalitet, 0, 100) / 100)).toFixed(1);
460	}
