462	/* ═══════════════════════════════════════════════════════════════
463	   6. МОТОР — еден тик ја движи целата игра
464	   ═══════════════════════════════════════════════════════════════ */
465	function tikni(){
466	  const prethodenDen = sostojba.den;
467	
468	  // ── Часовник ──────────────────────────────────────────────
469	  sostojba.chas += KONFIG.CHASA_PO_TIK;
470	  while (sostojba.chas >= 24){ sostojba.chas -= 24; sostojba.den++; }
471	  const novDen = sostojba.den !== prethodenDen;
472	
473	  const lampa = tekovnaLampa();
474	  const delDena = KONFIG.CHASA_PO_TIK / 24;   // колку од денот помина овој тик
475	
476	  // ── Растенија ─────────────────────────────────────────────
477	  for (let i = 0; i < sostojba.brojLei; i++){
478	    const r = sostojba.lei[i].rastenie;
479	    if (!r) continue;
480	    const sorta = najdiSorta(r.sorta);
481	    if (!sorta) continue;
482	
483	    r.vozrast += KONFIG.CHASA_PO_TIK;
484	    r.brojTikovi++;
485	
486	    // Потрошувачка на вода и храна
487	    r.voda    = stegni(r.voda    - KONFIG.VODA_PAD_DEN  * delDena, 0, 100);
488	    r.hraniva = stegni(r.hraniva - KONFIG.HRANA_PAD_DEN * delDena, 0, 100);
489	
490	    // Автоматика од надградбите
491	    if (sostojba.nadgradbi.navodnuvanje && r.voda < KONFIG.AVTO_VODA_PRAG)
492	      r.voda = KONFIG.AVTO_VODA_PRAG;
493	    if (sostojba.nadgradbi.rabotnik && r.hraniva < KONFIG.RABOTNIK_PRAG){
494	      r.hraniva = stegni(r.hraniva + KONFIG.HRANA_DOZA, 0, 100);
495	      if (r.stetnik === "azot") r.stetnik = null;
496	    }
497	
498	    // ── Здравје ───────────────────────────────────────────
499	    let delta = 0, dobro = true;
500	    if (r.voda    < KONFIG.VODA_MIN) { delta -= KONFIG.STETA_SUSA;    dobro = false; }
501	    if (r.voda    > KONFIG.VODA_MAX) { delta -= KONFIG.STETA_DAVENJE; dobro = false; }
502	    if (r.hraniva < KONFIG.HRANA_MIN){ delta -= KONFIG.STETA_GLAD;    dobro = false; }
503	    if (r.hraniva > KONFIG.HRANA_MAX){ delta -= KONFIG.STETA_PREGOR;  dobro = false; }
504	
505	    if (r.stetnik){
506	      const n = najdiNastan(r.stetnik);
507	      if (n){ delta -= n.steta; dobro = false; }
508	      r.deoviSoStetnik += delDena;
509	    }
510	    if (dobro) delta += KONFIG.OPORAVUVANJE;
511	
512	    r.zdravje = stegni(r.zdravje + delta, 0, 100);
513	    r.zbirZdravje += r.zdravje;
514	
515	    // ── Фаза ──────────────────────────────────────────────
516	    const t = sorta.traenje;
517	    const kNikn = KONFIG.CHASA_NIKNENJE * t;
518	    const kVeg  = kNikn + KONFIG.CHASA_VEGETACIJA * t;
519	    const kCvet = kVeg  + KONFIG.CHASA_CVETANJE  * t;
520	
521	    if      (r.vozrast < kNikn) r.faza = "NIKNENJE";
522	    else if (r.vozrast < kVeg)  r.faza = "VEGETACIJA";
523	    else if (r.vozrast < kCvet) r.faza = "CVETANJE";
524	    else {
525	      r.faza = "ZRELO";
526	      const preku = r.vozrast - kCvet - KONFIG.CHASA_ZRELO_PROZOR;
527	      if (preku > 0){
528	        // Презревањето трајно го симнува квалитетот преку здравјето
529	        r.zdravje = stegni(r.zdravje - KONFIG.KAZNA_PREZRELOST_DEN * delDena, 0, 100);
530	        if (!r.predupredenoPrezrelost){
531	          r.predupredenoPrezrelost = true;
532	          izvesti(TEKST.prezrelo, "greska");
533	        }
534	      }
535	    }
536	
537	    // ── Штетници ──────────────────────────────────────────
538	    if (!r.stetnik){
539	      let sansa = KONFIG.SANSA_STETNIK_DEN * delDena;
540	      if (sostojba.nadgradbi.klima) sansa *= KONFIG.KLIMA_NAMALUVANJE;
541	      if (Math.random() < sansa){
542	        const mozni = NASTANI.filter(n => !n.samoCvetanje || r.faza === "CVETANJE");
543	        r.stetnik = mozni[Math.floor(Math.random() * mozni.length)].id;
544	        panelValjaSe = true;
545	      }
546	    }
547	  }
548	
549	  // ── Сушара ────────────────────────────────────────────────
550	  // Панелот се освежува само кога ќе се смени ЦЕЛ ден, инаку би се
551	  // прецртувал 4 пати во секунда и постојано би го ресетирал скролот.
552	  const brzina = sostojba.nadgradbi.sushara ? KONFIG.SUSHARA_ZABRZUVANJE : 1;
553	  for (const serija of sostojba.sushara){
554	    const prethoden = Math.floor(serija.denovi);
555	    serija.denovi += delDena * brzina;
556	    if (Math.floor(serija.denovi) !== prethoden) panelValjaSe = true;
557	  }
558	
559	  // ── Пазар — еднаш дневно ──────────────────────────────────
560	  if (novDen){
561	    for (const s of SORTI){
562	      const drift = 1 + (Math.random() - 0.5) * 2 * KONFIG.PAZAR_DRIFT;
563	      sostojba.pazar[s.id] = stegni((sostojba.pazar[s.id] || 1) * drift,
564	                                     KONFIG.PAZAR_MIN, KONFIG.PAZAR_MAX);
565	    }
566	    panelValjaSe = true;
567	  }
568	
569	  // ── Зачувување ────────────────────────────────────────────
570	  if (++brojacTikovi % KONFIG.AVTOSEJV_TIKOVI === 0) zachuvaj();
571	}
