580	  if (!naplati(s.cena)) return;
581	  sostojba.semki[id] = (sostojba.semki[id] || 0) + 1;
582	  izvesti(TEKST.kupenoSeme(s.ime));
583	  panelValjaSe = true;
584	  iscrtajSe();
585	}
