662	  const suvo   = presmetajPrinos(sorta, prosekZdravje, tekovnaLampa());
663	  const vlazno = suvo / KONFIG.VLAZNO_VO_SUVO;
664	
665	  sostojba.sushara.push({
666	    id: sledenId++, sorta: r.sorta,
667	    gramaVlazno: vlazno, denovi: 0,
668	    prosekZdravje, deoviSoStetnik: r.deoviSoStetnik
669	  });
670	  sostojba.lei[indeks].rastenie = null;
671	  sostojba.statistika.vkupnoBerbi++;
672	
673	  izvesti(TEKST.berba(Math.round(vlazno), sorta.ime), "pari");
674	  aktivnoJazice = "sushara";
675	  panelValjaSe = true;
676	  iscrtajSe();
