679	function zavrsiSushenje(serijaId){
680	  const idx = sostojba.sushara.findIndex(s => s.id === serijaId);
681	  if (idx === -1) return;
682	  const serija = sostojba.sushara[idx];
683	  const sorta = najdiSorta(serija.sorta); if (!sorta) return;
684	
685	  const tochnost = tochnostOdSushenje(Math.floor(serija.denovi), sostojba.nadgradbi.sushara);
686	  const kvalitet = presmetajKvalitet(
687	    serija.prosekZdravje, tochnost, sorta.genetika,
688	    tekovnaLampa().kvalitetBonus, Math.floor(serija.deoviSoStetnik)
689	  );
690	  const ocenka = najdiOcenka(kvalitet);
691	  const grama  = serija.gramaVlazno * KONFIG.VLAZNO_VO_SUVO;
692	
693	  sostojba.magacin.push({
694	    id: sledenId++, sorta: serija.sorta,
695	    grama, kvalitet, ocenka: ocenka.ime, ocenkaMult: ocenka.mult,
696	    klasa: ocenka.klasa, thc: null, testirano: false
697	  });
698	  sostojba.sushara.splice(idx, 1);
699	  sostojba.statistika.vkupnoGrama += grama;
700	
701	  izvesti(TEKST.sushenjeGotovo(Math.round(grama), ocenka.ime), "pari");
702	  aktivnoJazice = "magacin";
703	  panelValjaSe = true;
704	  iscrtajSe();
705	}
