707	function testirajVoLaboratorija(serijaId){
708	  const p = sostojba.magacin.find(m => m.id === serijaId);
709	  if (!p || p.testirano) return;
710	  const sorta = najdiSorta(p.sorta); if (!sorta) return;
711	  if (!naplati(KONFIG.CENA_LABORATORIJA)) return;
712	  p.thc = presmetajTHC(p.kvalitet, sorta.genetika);
713	  p.testirano = true;
714	  izvesti(TEKST.analiza(p.thc), "pari");
715	  panelValjaSe = true;
716	  iscrtajSe();
717	}
