719	function cenaNaSerija(p){
720	  const sorta = najdiSorta(p.sorta); if (!sorta) return 0;
721	  const pazar = sostojba.pazar[p.sorta] || 1;
722	  return p.grama * sorta.cenaPoGram * pazar * p.ocenkaMult
723	         * (p.testirano ? KONFIG.BONUS_LABORATORIJA : 1);
724	}
