884	function iscrtajLeja(i){
885	  const j = lejaJazli[i];
886	  const otklucena = i < sostojba.brojLei;
887	  const r = sostojba.lei[i].rastenie;
888	
889	  // Прикажи ги отклучените леи плус ЕДНА следна, како понуда за купување.
890	  j.koren.style.display = (otklucena || i === sostojba.brojLei) ? "" : "none";
891	
892	  // ── Заклучена леја ──────────────────────────────────────
893	  if (!otklucena){
894	    j.koren.className = "leja zaklucena";
895	    j.faza.textContent = "";
896	    j.znakSorta.textContent = "";
897	    j.znakStetnik.textContent = "";
898	    j.prazna.textContent = "Заклучена леја";
899	    j.prazna.style.display = "";
900	    skrijRastenie(j);
901	    postaviAkcii(j, sostojba.brojLei < KONFIG.MAX_LEI
902	      ? `<button class="glavna" onclick="otkluchiLeja()">Отклучи · ${formatPari(cenaNaSlednaLeja())} ден</button>`
903	      : "");
904	    isprazniLenti(j, "");
905	    return;
906	  }
907	
908	  // ── Празна леја ─────────────────────────────────────────
909	  if (!r){
910	    j.koren.className = "leja";
911	    j.faza.textContent = "Празна";
912	    j.znakSorta.textContent = "";
913	    j.znakStetnik.textContent = "";
914	    j.prazna.textContent = "Празна леја";
915	    j.prazna.style.display = "";
916	    skrijRastenie(j);
917	    postaviAkcii(j, `<button class="glavna" onclick="otvoriIzborSeme(${i})">Засади</button>`);
918	    isprazniLenti(j, "—");
919	    return;
920	  }
921	
922	  // ── Засадена леја ───────────────────────────────────────
923	  const sorta = najdiSorta(r.sorta);
924	  const zrela = r.faza === "ZRELO";
925	  const bolna = r.zdravje < 45 || !!r.stetnik;
926	  j.koren.className = "leja" + (zrela ? " zrela" : "") + (bolna ? " bolna" : "");
927	  j.faza.textContent = FAZI[r.faza] ? FAZI[r.faza].ime : "—";
928	  j.prazna.style.display = "none";
929	  j.znakSorta.textContent = sorta ? sorta.ime : "?";
930	
931	  if (r.stetnik){
932	    const n = najdiNastan(r.stetnik);
933	    j.znakStetnik.textContent = n ? n.kratko : "!";
934	    j.znakStetnik.title = n ? n.ime : "";
935	  } else {
936	    j.znakStetnik.textContent = "";
937	    j.znakStetnik.title = "";
938	  }
939	
940	  // Геометрија на растот
941	  const traenje = sorta ? sorta.traenje : 1;
942	  const vkupno = sorta ? vkupnoChasaDoZrelost(sorta) : 1;
943	  const rast = stegni(r.vozrast / vkupno, 0, 1);
944	  const zdr  = r.zdravje / 100;
945	
946	  // Визуелната крива е поблага од вистинскиот раст на времето, за да има
947	  // што да се гледа и во првите секунди — инаку никулецот е точка на екранот.
948	  const vid = Math.pow(rast, 0.65);
949	  const visina = 14 + 70 * vid;
950	  const vrv = 118 - visina;                    // Y-координата на врвот на стеблото
951	  j.steblo.setAttribute("height", visina.toFixed(1));
952	  j.steblo.setAttribute("y", vrv.toFixed(1));
953	
954	  // Лисјата седат на фиксни ДЕЛОВИ од височината на стеблото, не на фиксни
955	  // координати — инаку кај младо растение лебдат во воздух над стеблото.
956	  j.lisja.forEach((g, idx) => {
957	    const y = 118 - visina * FRAKCII_LISJA[idx];
958	    const lokalno = stegni((vid - idx * 0.22) / 0.35, 0, 1);
959	    g.style.transform = `translate(50px,${y.toFixed(1)}px) scale(${lokalno.toFixed(3)})`;
960	  });
961	
962	  // Пупките никнуваат на врвот, па и тие се симнуваат заедно со стеблото.
963	  const pochetokCvet = (KONFIG.CHASA_NIKNENJE + KONFIG.CHASA_VEGETACIJA) * traenje;
964	  const cvet = (r.faza === "CVETANJE" || zrela)
965	    ? stegni((r.vozrast - pochetokCvet) / (KONFIG.CHASA_CVETANJE * traenje), 0, 1)
966	    : 0;
967	  j.pupki.setAttribute("opacity", cvet.toFixed(2));
968	  j.pupki.style.transform = `translate(0px,${(vrv - 34).toFixed(1)}px)`;
969	
970	  // Бојата паѓа од зелена кон кафеава како што паѓа здравјето. Пупките мора
971	  // да ја следат — инаку мртво растение и понатаму изгледа сочно зелено.
972	  const nijansa = 25 + 85 * zdr, zasit = 30 + 50 * zdr, svetlo = 22 + 18 * zdr;
973	  j.boja.setAttribute("fill",
974	    `hsl(${nijansa.toFixed(0)} ${zasit.toFixed(0)}% ${svetlo.toFixed(0)}%)`);
975	  j.pupki.setAttribute("fill",
976	    `hsl(${(nijansa + 12).toFixed(0)} ${(zasit + 15).toFixed(0)}% ${(svetlo + 20).toFixed(0)}%)`);
977	
978	  // Ленти
979	  postaviLenta(j.bVoda, j.uVoda, r.voda,
980	    (r.voda < KONFIG.VODA_MIN || r.voda > KONFIG.VODA_MAX) ? "var(--crvena)" : "var(--sina)");
981	  postaviLenta(j.bHrana, j.uHrana, r.hraniva,
982	    (r.hraniva < KONFIG.HRANA_MIN || r.hraniva > KONFIG.HRANA_MAX) ? "var(--crvena)" : "var(--zelena)");
983	  postaviLenta(j.bZdravje, j.uZdravje, r.zdravje,
984	    r.zdravje < 45 ? "var(--crvena)" : r.zdravje < 75 ? "var(--zlato)" : "var(--zelena)");
985	
986	  // Дугмиња
987	  let html = "";
988	  if (zrela) html += `<button class="zlatna" onclick="oberi(${i})">Обери</button>`;
989	  html += `<button onclick="polej(${i})">Полеј</button>`;
990	  html += `<button onclick="nahrani(${i})">Ѓубри · ${KONFIG.CENA_HRANA}</button>`;
991	  if (r.stetnik){
992	    const n = najdiNastan(r.stetnik);
993	    html += (n && n.tretman)
994	      ? `<button class="opasna" onclick="tretiraj(${i})">${n.tretman} · ${n.cena} ден</button>`
995	      : `<button class="opasna" onclick="nahrani(${i})">Ѓубри против азот</button>`;
996	  }
997	  postaviAkcii(j, html);
998	}
